rule.definition:
a!localVariables(
  local!queryDataSubset:#"SYSTEM_SYSRULES_queryEntity_v1"(
    entity: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6906905",
    query: #"SYSTEM_SYSRULES_query"(
      logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
        operator: "AND",
        ignorefilterswithemptyvalues: true,
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "fiscalYear", 
            operator: "=", 
            value: ri!fiscalYear, 
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "regionId",
            operator: "in",
            value: ri!regionId
          )
        }
      ),
      paginginfo: #"SYSTEM_SYSRULES_pagingInfo"(
        startIndex: 1,
        batchSize: -1
      )
    )
  ),
  cast(
    'type!{urn:com:appian:types:CAW}CAW_V_ROTATIONAL_ASK_PLAN?list',
    local!queryDataSubset.data
  )
)
